/// Performs a stable merge sort on a slice of elements.
///
/// This function allocates a new `Vec<T>` containing the sorted elements.
/// It uses a classic divide-and-conquer approach:
/// 1. Recursively splits the slice into halves until base cases are reached.
/// 2. Merges the sorted halves back together.
///
/// # Complexity
/// - **Time:** O(n log n) in all cases (best, average, and worst).
/// - **Space:** O(n) due to the allocation of temporary buffers during the merge step.
///
/// # Type Constraints
/// - `T` must implement `Ord` for comparison.
/// - `T` must implement `Clone` because the merge step creates new instances.
///
/// # Example
/// ```
/// let data = vec![3, 1, 2];
/// let sorted = merge_sort::merge_sort(&data);
/// assert_eq!(sorted, vec![1, 2, 3]);
/// ```
pub fn merge_sort<T: Ord + Clone>(v: &[T]) -> Vec<T> {
    if v.len() <= 1 {
        return v.to_vec();
    }

    let mid = v.len() / 2;
    let left = merge_sort(&v[..mid]);
    let right = merge_sort(&v[mid..]);

    merge(&left, &right)
}

/// Merges two sorted slices into a single sorted vector.
///
/// This helper function takes two already-sorted vectors and combines them
/// into one sorted vector. It is the core operation of the merge sort algorithm.
///
/// # Complexity
/// - **Time:** O(n + m), where n and m are the lengths of the input slices.
