	wg sync.WaitGroup

	// shutdownCh signals workers to stop processing new work.
	shutdownCh chan struct{}

	// resultsCh collects errors from workers.
	resultsCh chan error

	// closed is an atomic flag indicating if the pool has been shut down.
	closed int32

	// wgResults waits for all workers to finish and drain results.
	wgResults sync.WaitGroup
}

// New creates a new worker pool with the specified number of workers.
// The pool starts immediately with the given number of workers.
