	if n <= 0 {
		return nil, fmt.Errorf("invalid number of workers: %d", n)
	}

	p := &Pool{
		numWorkers: n,
		workQueue:  make(chan func() error, n), // Buffered to prevent blocking on submit
		shutdownCh: make(chan struct{}),
		resultsCh:  make(chan error, n),        // Buffered to prevent blocking on result collection
	}

	// Start workers
	for i := 0; i < n; i++ {
